/* @lc app=leetcode id=3420 lang=kotlin */ class Solution { fun cost(a: IntArray, f: LongArray, up: Array<IntArray>, p: LongArray, l: Int, r: Int): Long = (16 downTo 0).fold(l) { c, k -> if (up[k][c] <= r) up[k][c] else c }.let { c -> f[l] - f[c] + a[c].toLong() * (r - c + 1) - (p[r + 1] - p[l]) } fun countNonDecreasingSubarrays(nums: IntArray, k: Int): Long = nums.size.let { n -> IntArray(n + 1) { n }.also { g -> java.util.ArrayDeque<Int>().let { st -> nums.indices.forEach { i -> generateSequence { st.peekFirst()?.takeIf { nums[it] < nums[i] } }.forEach { _ -> st.pollFirst().let { g[it] = i } }.let { st.addFirst(i) } } } }.let { g -> LongArray(n + 1).also { f -> (n - 1 downTo 0).forEach { i -> f[i] = nums[i].toLong() * (g[i] - i) + f[g[i]] } }.let { f -> Array(17) { IntArray(n + 1) }.also { up -> g.copyInto(up[0]) }.also { up -> (1 until 17).forEach { k2 -> (0..n).forEach { i -> up[k2][i] = up[k2 - 1][up[k2 - 1][i]] } } }.let { up -> nums.runningFold(0L) { a, b -> a + b }.toLongArray().let { p -> nums.indices.fold(0 to 0L) { (l, ans), r -> generateSequence(l) { ll -> if (cost(nums, f, up, p, ll, r) > k) ll + 1 else null }.last().let { l2 -> l2 to ans + (r - l2 + 1) } }.second } } } } } }